/// url = 'https://icr.healthcampaigns.org/StructureMap/StageDIGITFacility'
/// name = 'StageDIGITFacility'
/// status = 'draft'

// A DIGIT facility as a staged Basic, for the StgFacility view: its fields,
// unchanged, each in an extension named after it. The DigitFacility Library
// joins them with the exported boundaries, and DIGITFacilityToICR maps the
// result. Staged resources are not written to the output.
uses "https://icr.healthcampaigns.org/StructureDefinition/DIGITFacility" alias DIGITFacility as source
uses "http://hl7.org/fhir/StructureDefinition/Basic" alias Basic as target

group StageFacility(source src : DIGITFacility, target b : Basic) {
  src.id as id -> b.id = id "id";
  src -> b.code as k, k.text = 'digit-facility' "kind";
  src.clientReferenceId as v -> b.extension as e, e.url = 'https://icr.healthcampaigns.org/StructureDefinition/staging-clientReferenceId', e.value = v "clientReferenceId";
  src.name as v -> b.extension as e, e.url = 'https://icr.healthcampaigns.org/StructureDefinition/staging-name', e.value = v "name";
  src.usage as v -> b.extension as e, e.url = 'https://icr.healthcampaigns.org/StructureDefinition/staging-usage', e.value = v "usage";
  src.isPermanent as v -> b.extension as e, e.url = 'https://icr.healthcampaigns.org/StructureDefinition/staging-isPermanent', e.value = v "isPermanent";
  src.isDeleted as v -> b.extension as e, e.url = 'https://icr.healthcampaigns.org/StructureDefinition/staging-isDeleted', e.value = v "isDeleted";
  src.address as a then {
    a.latitude as v -> b.extension as e, e.url = 'https://icr.healthcampaigns.org/StructureDefinition/staging-latitude', e.value = v "latitude";
    a.longitude as v -> b.extension as e, e.url = 'https://icr.healthcampaigns.org/StructureDefinition/staging-longitude', e.value = v "longitude";
    a.locality as l, l.code as v -> b.extension as e, e.url = 'https://icr.healthcampaigns.org/StructureDefinition/staging-locality', e.value = v "locality";
  } "address";
}
